33	    {
34	        incrementAge(maxAge);
35	        decrementFoodLevel();
36	        updateBurnStatus(step.getWeather());
37	        if(isAlive()) {
38	            addOffspring(newAnimals, calculateBirths(breedingAge, breedingProbability, maxLitterSize),
39	                         (field, location) -> createYoung(field, location));
40	            Location newLocation = findFood();
