108	    /**
109	     * Run the simulation from its current state for a single step.
110	     * Iterate over the whole field updating the state of each
111	     * fox and rabbit.
112	     */
113	    public void simulateOneStep()
114	    {
115	        step++;
116	        updateWeather();
117	        SimulationStep currentStep = new SimulationStep(step, weather);
118	        
119	        // Provide space for newborn animals.
120	        List<Animal> newAnimals = new ArrayList<>();        
121	        // Let all animals act.
122	        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
123	            Animal animal = it.next();
124	            animal.act(newAnimals, currentStep);
125	            if(! animal.isAlive()) {
126	                it.remove();
127	            }
128	        }
129	               
130	        // Add the newly born foxes and rabbits to the main lists.
131	        animals.addAll(newAnimals);
132	
133	        // Let all plants act.
134	        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
135	            Plant plant = it.next();
136	            plant.act(currentStep);
137	            if(! plant.isAlive()) {
138	                it.remove();
139	            }
140	        }
141	        
142	        view.showStatus(currentStep, field);
143	    }
